// Quantized model calibration seed generated by model/tiny_yolo_train_export.py.
// The full INT8 tensor is loaded by the XNN build when available; this small
// ROM keeps a deterministic model parameter in the standalone RTL baseline.
module tiny_yolo_weights_rom(
    output wire signed [7:0] weight_seed,
    output wire signed [31:0] bias_seed
);
    assign weight_seed = -8'sd25;
    assign bias_seed = 32'sh0000371b;
endmodule
